import { Wnd } from "../Wnd";
import { getAllModels } from "../getAll";
import { Model } from "../Model";
import { adjustLayout, saveLayout } from "../util";
import { setPanelFocus } from "../utils/setPanelFocus";
import { getDockByType, resizeTabs } from "../tabUtil";
import { Protyle } from "../../protyle";
import { resetFloatDockSize } from "./util";
import { App } from "../../index";
import { Custom } from "./Custom";
import { recordBeforeResizeTop } from "../../protyle/util/resize";
import { Constants } from "../../constants";
import { createDockTab } from "./dock.factory";
import { initDockResize } from "./dock.resize";
import { initDockDnD } from "./dock.dnd";
import { initDockLayout } from "./dock.layout";
import {
    handlePanelFocusSwitch,
    handleGraphDestroy,
    handlePostCloseFocus,
    handleTabSwitch,
    updateDockPanelRelation,
    updatePanelVisibility,
    handleGraphShow,
    handleDockHideSize,
    setDockLayoutSize,
    handleGraphFullscreenDrag,
    blurActiveElement
} from "./dock.toggle";
import {
    generateAllButtonsHTML,
    insertButtonsToContainer
} from "./dock.button";
import {
    getSiyuanLanguages,
    getSiyuanConfig,
    getSiyuanLayout,
    incrementSiyuanZIndex,
    getWindowInnerWidth,
    getWindowInnerHeight,
    setWindowTimeout,
    clearWindowTimeout
} from "./dock.environment";
import { isWnd, isTDock } from "./dock.guard";

const TYPES = ["file", "outline", "inbox", "bookmark", "tag", "graph", "globalGraph", "backlink"];

export class Dock {
    public element!: HTMLElement;
    public layout!: Layout;
    public position: TDockPosition;
    private app: App;
    public resizeElement!: HTMLElement;
    public pin = true;
    public data: { [key in TDock | string]?: Model | boolean } = {};
    private hideResizeTimeout = 0;

    constructor(options: {
        app: App,
        data: {
            pin: boolean,
            data: Config.IUILayoutDockTab[][]
        },
        position: TDockPosition
    }) {
        this.app = options.app;
        this.position = options.position;
        this.pin = options.data.pin;
        this.data = {};
        this.initLayout(options.position);

        const dockElement = document.getElementById("dock" + options.position);
        if (!dockElement) {
            throw new Error(`Dock element not found: dock${options.position}`);
        }
        this.element = dockElement;

        const dockClass = options.position === "Bottom" ? ' class="fn__flex dock__items"' : ' class="dock__items"';
        this.element.innerHTML = `<div${dockClass}></div><div class="fn__flex-1 dock__item--space"></div><div${dockClass}></div>`;

        this.initDockData(options.data.data);
        this.initEvents();

        initDockResize(this);
        initDockDnD(this);

        const config = getSiyuanConfig();
        if (config?.uiLayout?.hideDock) {
            this.element.classList.add("fn__none");
        }
        if (!this.pin) {
            this.initFloatDock();
        }
    }

    private initFloatDock(): void {
        // @鍐呰仈鍥炶皟
        setWindowTimeout(() => {
            this.resetDockPosition(false);
            this.hideDock(true);
            this.layout.element.classList.add("layout--float");
            this.resizeElement.classList.add("fn__none");
        });
    }

    private initLayout(position: TDockPosition): void {
        initDockLayout(this, position);
    }

    private initDockData(data: Config.IUILayoutDockTab[][]): void {
        const hasType = (item: Config.IUILayoutDockTab) => TYPES.includes(item.type);
        const firstHasType = data[0]?.find(hasType);
        const secondHasType = data[1]?.find(hasType);
        const showDock = Boolean(firstHasType) || Boolean(secondHasType);

        if (!showDock) {
            this.renderPin();
            this.element.classList.add("fn__none");
            this.initDockFiles();
            this.initDockActive();
            return;
        }

        if (data[0]) this.genButton(data[0], 0);
        if (data[1]) this.genButton(data[1], 1);
        this.element.classList.remove("fn__none");
        this.initDockFiles();
        this.initDockActive();
    }

    private renderPin(): void {
        const languages = getSiyuanLanguages();
        if (!languages) return;
        const unpin = languages.unpin;
        const pin = languages.pin;
        const firstChild = this.element.firstElementChild;
        if (!firstChild) return;
        firstChild.innerHTML = `<span class="dock__item dock__item--pin ariaLabel" aria-label="${this.pin ? unpin : pin}">
    <svg><use xlink:href="#icon${this.pin ? "Unpin" : "Pin"}"></use></svg>
</span>`;
    }

    private initDockFiles(): void {
        const dockItems = this.element.querySelectorAll(".dock__item");
        for (const item of Array.from(dockItems)) {
            const isFileType = item.getAttribute("data-type") === "file";
            const isNotActive = !item.classList.contains("dock__item--active");
            if (isFileType && isNotActive) {
                this.toggleModel("file", true, false, false, false);
                this.toggleModel("file", false, false, false, false);
            }
        }
    }

    private initDockActive(): void {
        const activeElements = Array.from(this.element.querySelectorAll(".dock__item--active"));
        if (activeElements.length > 0) {
            this.initActiveElements(activeElements);
            return;
        }
        this.initNoActiveElements();
    }

    private initActiveElements(activeElements: Element[]): void {
        for (const item of activeElements) {
            const type = item.getAttribute("data-type");
            if (isTDock(type)) {
                this.toggleModel(type, true, false, false, false);
            }
        }
    }

    private initNoActiveElements(): void {
        this.resizeElement.classList.add("fn__none");
        const children = this.layout.children;
        if (!children || children.length <= 1) return;

        for (const child of children) {
            child.element.classList.add("fn__none");
        }
        const firstChild = children[0];
        const nextSibling = firstChild?.element?.nextElementSibling;
        if (nextSibling) {
            nextSibling.classList.add("fn__none");
        }
    }

    private initEvents(): void {
        this.element.addEventListener("click", this.onClick.bind(this));
        this.layout.element.addEventListener("mouseleave", this.onMouseLeave.bind(this));
    }

    private onMouseLeave(event: MouseEvent): void {
        const toElement = event.relatedTarget;
        if (!(toElement instanceof HTMLElement)) {
            if (event.buttons !== 0 || this.pin) return;
            this.hideDock();
            return;
        }

        const isMenuOrTooltip = toElement.classList.contains("b3-menu") || toElement.classList.contains("tooltip");
        if (event.buttons !== 0 || this.pin || isMenuOrTooltip) return;
        if (this.position === "Left" && event.clientX < 43) return;
        if (this.position === "Right" && event.clientX > getWindowInnerWidth() - 43) return;
        if (this.position === "Bottom" && event.clientY > getWindowInnerHeight() - 73) return;
        this.hideDock();
    }

    private onClick(event: MouseEvent): void {
        let target = event.target;
        if (!(target instanceof HTMLElement)) return;

        while (target && !target.isEqualNode(this.element)) {
            const type = target.getAttribute("data-type");
            if (isTDock(type)) {
                this.toggleModel(type, false, true);
                event.preventDefault();
                return;
            }
            if (target.classList.contains("dock__item")) {
                this.handlePinClick(target, event);
                return;
            }
            const parent = target.parentElement;
            if (!(parent instanceof HTMLElement)) return;
            target = parent;
        }
    }

    private handlePinClick(target: HTMLElement, event: MouseEvent): void {
        this.togglePin();
        const languages = getSiyuanLanguages();
        const unpin = languages?.unpin;
        const pin = languages?.pin;
        if (unpin && pin) {
            target.setAttribute("aria-label", this.pin ? unpin : pin);
        }
        const use = target.querySelector("use");
        if (use) {
            use.setAttribute("xlink:href", this.pin ? "#iconUnpin" : "#iconPin");
        }
        event.preventDefault();
    }

    public togglePin(): void {
        this.pin = !this.pin;
        const hasActive = this.element.querySelector(".dock__item--active");

        if (!this.pin) {
            this.resetDockPosition(Boolean(hasActive));
            this.resizeElement.classList.add("fn__none");
            if (hasActive) {
                this.showDock(true);
            }
            if (!hasActive) {
                this.hideDock(true);
            }
            this.layout.element.classList.toggle("layout--float");
            resizeTabs();
            return;
        }

        this.layout.element.style.opacity = "";
        this.layout.element.style.transform = "";
        this.layout.element.style.zIndex = "";
        if (hasActive) {
            this.resizeElement.classList.remove("fn__none");
        }
        this.layout.element.classList.toggle("layout--float");
        resizeTabs();
    }

    public resetDockPosition(show: boolean): void {
        const opacity = show ? 1 : 0;
        if (this.position === "Left" || this.position === "Right") {
            this.layout.element.setAttribute("style", `width:${this.layout.element.clientWidth}px;opacity:${opacity};`);
            return;
        }
        this.layout.element.setAttribute("style", `height:${this.layout.element.clientHeight}px;opacity:${opacity};`);
    }

    public showDock(reset = false): void {
        if (!reset && this.shouldSkipShowDock()) return;
        if (!reset && this.isZeroSize()) return;
        if (this.hasBlockingOverlay()) return;

        if (!reset) {
            this.layout.element.style.opacity = "1";
        }
        this.layout.element.style.transform = "";
        this.layout.element.style.zIndex = incrementSiyuanZIndex().toString();
        this.setDockPosition();
    }

    private shouldSkipShowDock(): boolean {
        const hasActiveItem = this.element.querySelector(".dock__item--active");
        return this.pin || !hasActiveItem || this.layout.element.style.opacity === "1";
    }

    private isZeroSize(): boolean {
        const isHorizontal = this.position === "Left" || this.position === "Right";
        if (isHorizontal) {
            return this.layout.element.clientWidth === 0 && this.layout.element.style.width.startsWith("0");
        }
        if (this.position === "Bottom") {
            return this.layout.element.clientHeight === 0 && this.layout.element.style.height.startsWith("0");
        }
        return false;
    }

    private hasBlockingOverlay(): boolean {
        const hasDialog = document.querySelector(".b3-dialog");
        const hasPopover = document.querySelector(".block__popover");
        const hasMenu = document.querySelector("#commonMenu:not(.fn__none)");
        if (!hasDialog && !hasPopover && !hasMenu) return false;

        const siyuanLayout = getSiyuanLayout();
        const leftOpacity = siyuanLayout?.leftDock?.layout?.element?.style?.opacity === "1";
        const rightOpacity = siyuanLayout?.rightDock?.layout?.element?.style?.opacity === "1";
        const bottomOpacity = siyuanLayout?.bottomDock?.layout?.element?.style?.opacity === "1";
        return leftOpacity || rightOpacity || bottomOpacity;
    }

    private setDockPosition(): void {
        if (this.position === "Left") {
            this.layout.element.style.left = `${this.element.clientWidth}px`;
            return;
        }
        if (this.position === "Right") {
            this.layout.element.style.right = `${this.element.clientWidth}px`;
            return;
        }
        if (this.position === "Bottom") {
            const statusElement = document.getElementById("status");
            const statusHeight = statusElement?.offsetHeight || 0;
            this.layout.element.style.bottom = `${this.element.offsetHeight + statusHeight}px`;
        }
    }

    public hideDock(reset = false): void {
        if (!reset && (this.layout.element.style.opacity === "0" || this.pin)) return;
        if (this.isFullscreenActive()) return;
        if (this.isTextFieldFocused()) return;
        if (this.hasHigherZIndexOverlay()) return;

        this.applyHideTransform();
        if (reset) return;

        this.layout.element.style.opacity = "0";
        const activeFocusElement = this.element.querySelector(".dock__item--activefocus");
        if (activeFocusElement) {
            activeFocusElement.classList.remove("dock__item--activefocus");
        }
        const activeTabElement = this.layout.element.querySelector(".layout__tab--active");
        if (activeTabElement) {
            activeTabElement.classList.remove("layout__tab--active");
        }
    }

    private isFullscreenActive(): boolean {
        const fullscreenElement = this.layout.element.querySelector(".fullscreen");
        return Boolean(fullscreenElement && fullscreenElement.clientHeight > 0);
    }

    private isTextFieldFocused(): boolean {
        const activeEl = document.activeElement;
        if (!activeEl) return false;
        const isTextField = activeEl.classList.contains("b3-text-field");
        return this.layout.element.contains(activeEl) && isTextField;
    }

    private hasHigherZIndexOverlay(): boolean {
        const layoutZIndex = this.layout.element.style.zIndex;
        const dialogElement = document.querySelector(".b3-dialog");
        const blockElement = document.querySelector(".block__popover");
        const menuElement = document.querySelector("#commonMenu:not(.fn__none)");

        if (dialogElement instanceof HTMLElement && dialogElement.style.zIndex > layoutZIndex) return true;
        if (blockElement instanceof HTMLElement && blockElement.style.zIndex > layoutZIndex) return true;
        if (menuElement instanceof HTMLElement && menuElement.style.zIndex > layoutZIndex) return true;
        return false;
    }

    private applyHideTransform(): void {
        if (this.position === "Left") {
            this.layout.element.style.transform = `translateX(-${this.layout.element.clientWidth + 8}px)`;
            this.layout.element.style.left = "";
            return;
        }
        if (this.position === "Right") {
            this.layout.element.style.transform = `translateX(${this.layout.element.clientWidth + 8}px)`;
            this.layout.element.style.right = "";
            return;
        }
        if (this.position === "Bottom") {
            this.layout.element.style.transform = `translateY(${this.layout.element.clientHeight + 8}px)`;
            this.layout.element.style.bottom = "";
        }
    }

    public toggleModel(type: TDock | string, show = false, close = false, hide = false, isSaveLayout = true): void {
        if (!type) return;
        if (this.pin) recordBeforeResizeTop();

        const target = this.element.querySelector(`[data-type="${type}"]`);
        if (!(target instanceof HTMLElement)) return;

        if (show && target.classList.contains("dock__item--active")) {
            target.classList.remove("dock__item--active", "dock__item--activefocus");
        }
        const index = parseInt(target.getAttribute("data-index") || "0", 10);
        const wndChild = this.layout.children[index];
        if (!isWnd(wndChild)) return;
        const wnd = wndChild;

        const isActiveOrHide = target.classList.contains("dock__item--active") || hide;
        if (isActiveOrHide) {
            this.handleToggleHide(wnd, target, type, close, isSaveLayout);
        }
        if (!isActiveOrHide) {
            this.handleToggleShow(wnd, target, type, index);
        }

        this.updatePanelRelations(wnd, index, target, hide);
        resizeTabs(isSaveLayout);
        this.showDock();

        if (target.classList.contains("dock__item--active") && !hide) {
            handleGraphShow(type, this);
        }
    }

    private handleToggleHide(wnd: Wnd, target: HTMLElement, type: string, close: boolean, isSaveLayout: boolean): void {
        if (!close && handlePanelFocusSwitch(wnd, target, this)) return;

        target.classList.remove("dock__item--active", "dock__item--activefocus");
        const hasNoActiveItems = this.element.querySelectorAll(".dock__item--active").length === 0;
        if (handleDockHideSize(this, hasNoActiveItems)) {
            clearWindowTimeout(this.hideResizeTimeout);
            this.hideDock();
        }
        handleGraphDestroy(type, this);
        handlePostCloseFocus(isSaveLayout);
    }

    private handleToggleShow(wnd: Wnd, target: HTMLElement, type: string, index: number): void {
        const activeItems = this.element.querySelectorAll(`.dock__item--active[data-index="${index}"]`);
        for (const item of Array.from(activeItems)) {
            item.classList.remove("dock__item--active", "dock__item--activefocus");
        }
        target.classList.add("dock__item--active", "dock__item--activefocus");

        if (!target.getAttribute("data-id")) {
            this.createNewTab(wnd, target, type);
            return;
        }
        handleTabSwitch(wnd, target.getAttribute("data-id"));
        this.showDockWithResize(type);
    }

    private createNewTab(wnd: Wnd, target: HTMLElement, type: string): void {
        const editor = this.findActiveEditor();
        const tab = createDockTab({
            app: this.app,
            type,
            editor
        });
        wnd.addTab(tab, false, false);
        target.setAttribute("data-id", tab.id);
        this.data[type] = tab.model;
        setPanelFocus(tab.panelElement);
        this.showDockWithResize(type);
    }

    private findActiveEditor(): Protyle | undefined {
        const models = getAllModels();
        for (const item of models.editor) {
            const isFocused = item.parent.headElement.classList.contains("item--focus");
            const hasPath = item.editor?.protyle?.path;
            if (isFocused && hasPath) {
                return item.editor;
            }
        }
        return undefined;
    }

    private showDockWithResize(type: string): void {
        setDockLayoutSize(this, this.getMaxSize());
        handleGraphFullscreenDrag(type, this, true);
        if (!this.pin) return;

        this.layout.element.style.opacity = "";
        this.hideResizeTimeout = setWindowTimeout(() => {
            this.resizeElement.classList.remove("fn__none");
            adjustLayout();
        }, Constants.TIMEOUT_TRANSITION);
        blurActiveElement();
    }

    private updatePanelRelations(wnd: Wnd, index: number, target: HTMLElement, hide: boolean): void {
        const anotherIndex = index === 0 ? 1 : 0;
        const anotherChild = this.layout.children[anotherIndex];
        if (!isWnd(anotherChild)) return;
        const anotherWnd = anotherChild;

        const anotherHasActive = this.element.querySelectorAll(`.dock__item--active[data-index="${anotherIndex}"]`).length > 0;
        const hasActive = this.element.querySelectorAll(`.dock__item--active[data-index="${index}"]`).length > 0;

        updateDockPanelRelation(this, wnd, anotherWnd, index, anotherIndex, hasActive, anotherHasActive);
        updatePanelVisibility(wnd, anotherWnd, hasActive, anotherHasActive);
    }

    public add(index: number, sourceElement: Element, previousType?: string): void {
        sourceElement.setAttribute("data-height", "");
        sourceElement.setAttribute("data-width", "");

        const typeAttr = sourceElement.getAttribute("data-type");
        if (!isTDock(typeAttr)) return;
        const type = typeAttr;

        const sourceDock = getDockByType(type);
        const sourceIndex = parseInt(sourceElement.getAttribute("data-index") || "0", 10);
        this.removeSourceTab(sourceDock, sourceIndex, sourceElement);

        const hasActive = sourceElement.classList.contains("dock__item--active");
        if (hasActive && sourceDock) {
            sourceDock.toggleModel(type, false, false, false, false);
        }
        if (sourceDock) {
            delete sourceDock.data[type];
        }

        this.insertSourceElement(sourceElement, index, previousType);
        this.element.classList.remove("fn__none");
        resetFloatDockSize();
        this.data[type] = true;
        if (hasActive) {
            this.toggleModel(type, true, false, false, false);
        }
        // @鍐呰仈鍥炶皟
        setWindowTimeout(() => {
            saveLayout();
        }, Constants.TIMEOUT_TRANSITION);
    }

    private removeSourceTab(sourceDock: ReturnType<typeof getDockByType>, sourceIndex: number, sourceElement: Element): void {
        if (!sourceDock?.layout?.children) return;
        const sourceWnd = sourceDock.layout.children[sourceIndex];
        if (!isWnd(sourceWnd)) return;
        const sourceId = sourceElement.getAttribute("data-id");
        if (!sourceId) return;
        sourceWnd.removeTab(sourceId, false, true, false);
        sourceElement.removeAttribute("data-id");
    }

    private insertSourceElement(sourceElement: Element, index: number, previousType?: string): void {
        sourceElement.setAttribute("data-index", index.toString());
        if (previousType) {
            const prev = this.element.querySelector(`[data-type="${previousType}"]`);
            if (prev) {
                prev.after(sourceElement);
                return;
            }
        }
        const container = index === 0 ? this.element.firstElementChild : this.element.lastElementChild;
        if (!container) return;
        container.insertAdjacentElement("afterbegin", sourceElement);
    }

    public remove(key: TDock | string): void {
        if (isTDock(key)) {
            this.toggleModel(key, false, true, true);
        }
        const item = this.element.querySelector(`[data-type="${key}"]`);
        if (item) item.remove();

        const custom = this.data[key];
        if (custom instanceof Custom && custom.parent) {
            custom.parent.parent.removeTab(custom.parent.id);
        }
        delete this.data[key];
    }

    public setSize(): void {
        const activesElement = this.element.querySelectorAll(".dock__item--active");
        for (const item of Array.from(activesElement)) {
            this.setSizeForItem(item, activesElement.length);
        }
    }

    private setSizeForItem(item: Element, totalActive: number): void {
        const index = item.getAttribute("data-index");
        const type = item.getAttribute("data-type");
        if (!isTDock(type)) return;

        const isHorizontal = this.position === "Left" || this.position === "Right";
        if (isHorizontal) {
            this.setHorizontalSize(item, index, type, totalActive);
            return;
        }
        this.setVerticalSize(item, index, type, totalActive);
    }

    private setHorizontalSize(item: Element, index: string | null, type: TDock, totalActive: number): void {
        if (index === "1" && totalActive > 1) {
            const model = this.data[type];
            if (model instanceof Model) {
                const dockElement = model.parent.parent.element;
                const height = dockElement.style.height ? dockElement.clientHeight.toString() : "";
                item.setAttribute("data-height", height);
            }
        }
        item.setAttribute("data-width", this.layout.element.clientWidth.toString());
    }

    private setVerticalSize(item: Element, index: string | null, type: TDock, totalActive: number): void {
        if (index === "1" && totalActive > 1) {
            const model = this.data[type];
            if (model instanceof Model) {
                const dockElement = model.parent.parent.element;
                const width = dockElement.style.width ? dockElement.clientWidth.toString() : "";
                item.setAttribute("data-width", width);
            }
        }
        item.setAttribute("data-height", this.layout.element.clientHeight.toString());
    }

    private getMaxSize(): number {
        let max = 0;
        const activeItems = this.element.querySelectorAll(".dock__item--active");
        for (const item of Array.from(activeItems)) {
            const size = this.getSizeForItem(item);
            if (size > max) {
                max = size;
            }
        }
        return max;
    }

    private getSizeForItem(item: Element): number {
        const isHorizontal = this.position === "Left" || this.position === "Right";
        const sizeAttr = isHorizontal ? "data-width" : "data-height";
        const attrVal = item.getAttribute(sizeAttr);
        if (attrVal) {
            const parsed = parseInt(attrVal, 10);
            if (parsed > 0) return parsed;
        }

        const type = item.getAttribute("data-type");
        if (isHorizontal && type && ["graph", "globalGraph", "backlink"].includes(type)) {
            return 320;
        }
        return 232;
    }

    public genButton(data: Config.IUILayoutDockTab[], index: number, tabIndex?: number): void {
        const languages = getSiyuanLanguages();
        const dockTip = languages?.dockTip || "";
        const pinText = (this.pin ? languages?.unpin : languages?.pin) || "";

        const html = generateAllButtonsHTML(data, index, dockTip, tabIndex);

        for (const item of data) {
            this.data[item.type] = true;
        }

        const container = index === 0 ? this.element.firstElementChild : this.element.lastElementChild;
        insertButtonsToContainer(container, html, tabIndex, pinText, this.pin, index === 0);

        if (typeof tabIndex !== "number") return;

        const config = getSiyuanConfig();
        if (config && !config.uiLayout.hideDock) {
            this.element.classList.remove("fn__none");
        }

        const firstItem = data[0];
        if (firstItem?.show) {
            this.toggleModel(firstItem.type, true, false, false, false);
        }
    }
}
